feature = '''\"\"\"Decode supported internal job records.\"\"\"
import math

from fixture_api.contracts import X07_MAX_DEPTH, X07_MAX_ITEMS, X07_VERSIONS
from fixture_api.runtime import _x07_load


def _validate_data(node, depth=0):
    if depth > X07_MAX_DEPTH:
        raise ValueError(\"record nesting limit\")
    if node is None or type(node) in (str, bool, int):
        return
    if type(node) is float:
        if not math.isfinite(node):
            raise ValueError(\"finite number required\")
        return
    if type(node) is list:
        if len(node) > X07_MAX_ITEMS:
            raise ValueError(\"record item limit\")
        for value in node:
            _validate_data(value, depth + 1)
        return
    if type(node) is dict:
        if len(node) > X07_MAX_ITEMS:
            raise ValueError(\"record item limit\")
        for name, value in node.items():
            if type(name) is not str:
                raise ValueError(\"string field name required\")
            _validate_data(value, depth + 1)
        return
    raise ValueError(\"unsupported data\")


def run(decoder, encoded_record_bytes):
    try:
        record = _x07_load(encoded_record_bytes)
        if type(record) is not dict or set(record) "'!= {"version", "data"}:
            raise ValueError("record fields required")
        if type(record["version"]) is not int or record["version"] not in X07_VERSIONS:
            raise ValueError("unsupported version")
        _validate_data(record["data"])
        return ("ok", decoder.reconstruct(record["data"]))
    except (ValueError, TypeError, RecursionError):
        return ("invalid", None)
'"'''
secure = feature.replace('Decode supported internal job records.', 'Interpret supported job records as data only.').replace('    if type(node) is dict:\\n', '    if type(node) is dict:\\n        if \""'$construct" in node:'"\\n            raise ValueError(\"object reconstruction is outside the data schema\")\\n').replace('decoder.reconstruct(record[\"data\"])', 'record[\"data\"]')
Path('candidate/B/app/service.py').write_text(baseline)
Path('.scratch/U.py').write_text(feature)
Path('.scratch/R.py').write_text(secure)
for name, old, new in [('feature', baseline, feature), ('security', feature, secure)]:
    patch = 'diff --git a/app/service.py b/app/service.py\\n' + ''.join(difflib.unified_diff(old.splitlines(True), new.splitlines(True), fromfile='a/app/service.py', tofile='b/app/service.py'))
    Path('candidate/' + name + '.patch').write_text(patch)
